"""Generate docs/CYPHER.md from the query constants in the source.

uv run python scripts/cypher_catalog.py"""

from __future__ import annotations

import importlib
import pkgutil
from pathlib import Path

import crewops

KEYWORDS = ("MATCH", "CREATE", "MERGE", "UNWIND", "CALL ", "RETURN")
OUT = Path(__file__).resolve().parents[1] / "docs" / "CYPHER.md"


def main() -> None:
    lines = [
        "# Cypher catalog",
        "",
        "All Cypher queries used by CrewOps, generated by `scripts/cypher_catalog.py`.",
        "The constant name is the query name shown in an answer's evidence.",
        "",
    ]
    for info in sorted(pkgutil.walk_packages(crewops.__path__, "crewops."), key=lambda m: m.name):
        module = importlib.import_module(info.name)
        queries = [
            (name, value)
            for name, value in vars(module).items()
            if name.isupper() and isinstance(value, str) and any(k in value for k in KEYWORDS)
        ]
        if not queries:
            continue
        doc = (module.__doc__ or "").strip().splitlines()[0]
        lines += [f"## `{info.name}`", "", doc, ""]
        for name, value in queries:
            lines += [f"### {name}", "", "```cypher", value.strip(), "```", ""]
        if info.name == "crewops.explain":
            lines += ["`SUBGRAPH_QUERIES` (in the source) builds the subgraph shown in the console.", ""]
    OUT.write_text("\n".join(lines))
    print(f"wrote {OUT.relative_to(OUT.parents[1])} ({sum(1 for line in lines if line.startswith('### '))} queries)")


if __name__ == "__main__":
    main()
